doc.codeblock:
pub enum WorkspaceSecurityMode {
    Unknown,
    Plaintext,
    Encrypted { genesis_hash: String },
}

pub enum VerifiedPrincipal {
    LocalHost {
        caller_pid: Option<u32>,
        account_id: Option<UserId>,
    },
    ConnectedMember {
        profile_id: ProfileId,
        user_id: UserId,
    },
    EncryptedMember {
        profile_id: ProfileId,
        account_id: UserId,
        execution_user_id: UserId,
        device_pubkey_hex: String,
    },
}

pub trait ApplicationService: Send + Sync {
    fn execute(&self, caller: &VerifiedPrincipal, cmd: AppCommand) -> PortResult<AppResponse>;
    fn query(&self, caller: &VerifiedPrincipal, query: AppQuery) -> PortResult<AppResponse>;
}

pub fn enforce_command_policy(
    caller: &VerifiedPrincipal,
    cmd: &AppCommand,
    entitlement: Option<&EntitlementStatus>,
) -> PortResult<()>;
